SELECT user_id, login_id, email, name, password_hash, created_at, updated_at
FROM users
WHERE login_id = #{loginId}

SELECT user_id, login_id, email, name, created_at, updated_at
FROM users
WHERE email = #{email}

SELECT user_id, login_id, email, name, created_at, updated_at
FROM users
WHERE user_id = #{userId}
